function numberScore(v) {
  return typeof v === 'number' ? v : parseInt(v, 10);
}

/**
 * Get the score for a game.
 */
async function getScore(gameId) {
  const game = await queryOne('SELECT id, score, state FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');
  return { score: game.score, state: game.state };
}

module.exports = {
  createGame,
  getGame,
  getCurrentQuestion,
  pauseGame,
  resumeGame,
  submitAnswer,
  getScore
};

/**
 * Unit tests for game scoring invariants using the game engine's
 * submitAnswer logic backed by an in-memory fake db.
 *
 * Invariants under test:
 *  - Each correct answer to a not-yet-correctly-answered question = +1.
 *  - Re-answering a question must never increase score (idempotent).
 *  - An incorrect answer never changes score.
 *  - Score can never decrease (answering wrong after correct is a no-op).
 */
const { test } = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');

const DB_MODULE_PATH = require.resolve('@spacefractions/shared/db');
const ENGINE_MODULE_PATH = path.join(__dirname, '..', 'src', 'game-engine.js');

function buildEngine() {
  const store = {
    games: [],
    questions: [],
    answers: []
  };

  const questions = [
    { id: 1, prompt: 'q1', options: ['1/2', '1/3'], correct_answer: '1/2' },
    { id: 2, prompt: 'q2', options: ['3/4', '1/4'], correct_answer: '3/4' },
    { id: 3, prompt: 'q3', options: ['2/3', '1/2'], correct_answer: '2/3' }
  ];
  store.questions = questions;

  store.games.push({
    id: 1,
    user_id: 'user-1',
    state: 'playing',
    score: 0,
    question_ids: [1, 2, 3],
    current_question_index: 0
  });

  function findGame(id) { return store.games.find(g => g.id === id); }

  async function handleQuery(sql, params) {
    const s = sql.trim();
    if (/SELECT \* FROM games WHERE id = \$1$/.test(s)) {
      return { rows: store.games.filter(g => g.id === params[0]) };
    }
    if (/SELECT id, correct_answer FROM questions WHERE id = \$1/.test(s)) {
      return { rows: store.questions.filter(q => q.id === params[0]).map(q => ({ id: q.id, correct_answer: q.correct_answer })) };
    }
    if (/SELECT \* FROM game_answers WHERE game_id = \$1 AND question_id = \$2/.test(s)) {
      return { rows: store.answers.filter(a => a.game_id === params[0] && a.question_id === params[1]) };
    }
    if (/SELECT scored FROM game_answers WHERE game_id = \$1 AND question_id = \$2/.test(s)) {
      return { rows: store.answers.filter(a => a.game_id === params[0] && a.question_id === params[1]).map(a => ({ scored: a.scored })) };
    }
    if (/INSERT INTO game_answers /.test(s)) {
      const [gameId, questionId, answer, correct, scored] = params;
      const id = store.answers.length + 1;
      const row = { id, game_id: gameId, question_id: questionId, answer, correct, scored };
      store.answers.push(row);
      return { rows: [row] };
    }
    if (/UPDATE game_answers SET/.test(s)) {
      const [answer, correctStr, scoredStr, id] = params;
      const row = store.answers.find(a => a.id === id);
      if (row) { row.answer = answer; row.correct = correctStr; row.scored = scoredStr; }
      return { rows: [row] };
    }
    if (/UPDATE games SET score = score \+ \$1/.test(s)) {
      const game = findGame(params[1]);
      if (game) game.score += params[0];
      return { rows: [game] };
    }
    if (/UPDATE games SET current_question_index = \$1, state = \$2/.test(s)) {
      const game = findGame(params[2]);
      if (game) { game.current_question_index = params[0]; game.state = params[1]; }
      return { rows: [game] };
    }
    throw new Error(`Unexpected SQL: ${s}`);
  }

  const fakeDb = {
    query: async (sql, params) => handleQuery(sql, params),
    queryOne: async (sql, params) => {
      const r = await handleQuery(sql, params);
      return r.rows[0] || null;
    }
  };

  require.cache[DB_MODULE_PATH] = {
    id: DB_MODULE_PATH, filename: DB_MODULE_PATH, loaded: true, exports: fakeDb
  };
  delete require.cache[ENGINE_MODULE_PATH];
  const engine = require(ENGINE_MODULE_PATH);
  return { engine, store };
}

test('score starts at zero and increments once per distinct correct answer', async () => {
  const { engine } = buildEngine();

  // Answer q1 wrong then correct.
  let r = await engine.submitAnswer(1, 1, '1/3', 'user-1', false);
  assert.equal(r.correct, false);
  assert.equal(r.score, 0);

  r = await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  assert.equal(r.correct, true);
  assert.equal(r.score, 1);

  // Answer q2 correct.
  r = await engine.submitAnswer(1, 2, '3/4', 'user-1', false);
  assert.equal(r.correct, true);
  assert.equal(r.score, 2);

  // Answer q3 wrong.
  r = await engine.submitAnswer(1, 3, '1/2', 'user-1', false);
  assert.equal(r.correct, false);
  assert.equal(r.score, 2);
});

test('repeated correct answer to same question does not double-count', async () => {
  const { engine } = buildEngine();

  await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  let r = await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  assert.equal(r.score, 1);
});

test('score never decreases when a previously-correct question is re-answered wrong', async () => {
  const { engine } = buildEngine();

  await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  // The answer row is already scored=true. Re-answering wrong must not change score.
  const r = await engine.submitAnswer(1, 1, '1/3', 'user-1', false);
  assert.equal(r.correct, false);
  assert.equal(r.score, 1);
});

test('score caps at number of distinct questions', async () => {
  const { engine } = buildEngine();

  await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  await engine.submitAnswer(1, 2, '3/4', 'user-1', false);
  await engine.submitAnswer(1, 3, '2/3', 'user-1', false);
  const final = await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  assert.equal(final.score, 3);
});

test('full correct run yields max score and completed state', async () => {
  const { engine } = buildEngine();

  await engine.submitAnswer(1, 1, '1/2', 'user-1', false);
  await engine.submitAnswer(1, 2, '3/4', 'user-1', false);
  const r = await engine.submitAnswer(1, 3, '2/3', 'user-1', false);
  assert.equal(r.score, 3);
  assert.equal(r.gameState, 'completed');
});

/**
 * PostgreSQL database pool and query helpers.
 */

const { Pool } = require('pg');

let pool = null;

/**
 * Initialize the database pool.
 */
function initPool(config) {
  if (pool) return pool;

  pool = new Pool({
    host: config.PGHOST || process.env.PGHOST || 'localhost',
    port: parseInt(config.PGPORT || process.env.PGPORT || '5432', 10),
    database: config.PGDATABASE || process.env.PGDATABASE || 'spacefractions',
    user: config.PGUSER || process.env.PGUSER || 'spacefractions',
    password: config.PGPASSWORD || process.env.PGPASSWORD || 'spacefractions',
    max: 20,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000
  });

  pool.on('error', (err) => {
    console.error('Unexpected PostgreSQL pool error:', err);
  });

  return pool;
}

/**
 * Get the current pool instance.
 */
function getPool() {
  if (!pool) {
    throw new Error('Database pool not initialized. Call initPool() first.');
  }
  return pool;
}

/**
 * Execute a query with params.
 */
async function query(sql, params) {
  const client = await getPool().connect();
  try {
    const result = await client.query(sql, params);
    return result;
  } finally {
    client.release();
  }
}

/**
 * Execute a query and return a single row or null.
 */
async function queryOne(sql, params) {
  const result = await query(sql, params);
  return result.rows[0] || null;
}

/**
 * Run `fn(client)` inside a PostgreSQL transaction on a single dedicated
 * client. `client` supports `query` and `queryOne` (single-row helper).
 * Commits on success, rolls back on error. Releases the client to the pool
 * in all cases.
 *
 * @param {(client: {query: Function, queryOne: Function}) => Promise<any>} fn
 * @returns {Promise<any>} fn's return value
 */
async function withTransaction(fn) {
  const client = await getPool().connect();
  try {
    await client.query('BEGIN');
    const txClient = {
      query: (sql, params) => client.query(sql, params),
      queryOne: async (sql, params) => {
        const r = await client.query(sql, params);
        return r.rows[0] || null;
      }
    };
    let result;
    try {
      result = await fn(txClient);
      await client.query('COMMIT');
      return result;
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }
  } finally {
    client.release();
  }
}

/**
 * Run a migration from a SQL string on a single owned client inside a
 * transaction with proper rollback on error.
 *
 * The SQL content may contain arbitrary statements (multi-statement `DO $$`
 * blocks, `BEGIN`/`COMMIT` wrappers, etc.) that cannot be safely split on
 * semicolons. We execute the whole content in one `client.query()` call,
 * which runs it on a single connection.
 *
 * A given migration name is recorded in `_schema_migrations`; if it was
 * already applied we skip running it again, making repeated startup
 * (including concurrent startup of multiple services) safe and idempotent.
 *
 * @param {string} sqlContent - raw SQL migration text
 * @param {string} [name='migration'] - stable identifier for this migration
 */
async function runMigrations(sqlContent, name = 'migration') {
  const client = await getPool().connect();
  try {
    // Ensure the tracking table exists before recording/applying.
    await client.query(
      'CREATE TABLE IF NOT EXISTS _schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW())'
    );

    const applied = await client.query(
      'SELECT 1 FROM _schema_migrations WHERE name = $1',
      [name]
    );
    if (applied.rowCount > 0) {
      return { applied: false, name };
    }

    await client.query('BEGIN');
    try {
      // Run the full migration as one unit on this client. The script's own
      // BEGIN/COMMIT (if present) is nested implicitly; Postgres treats
      // nested BEGIN as a warning and the outer transaction governs.
      await client.query(sqlContent);
      await client.query(
        'INSERT INTO _schema_migrations (name) VALUES ($1)',
        [name]
      );
      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }

    return { applied: true, name };
  } finally {
    client.release();
  }
}

/**
 * Health check: can we connect to the database?
 */
async function healthCheck() {
  try {
    await query('SELECT 1');
    return true;
  } catch (err) {
    console.error('Database health check failed:', err.message);
    return false;
  }
}

/**
 * Close the pool.
 */
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

module.exports = {
  initPool,
  getPool,
  query,
  queryOne,
  withTransaction,
  runMigrations,
  healthCheck,
  closePool
};

