/**
 * PostgreSQL database pool and query helpers.
 */

const { Pool } = require('pg');

let pool = null;

/**
 * Initialize the database pool.
 */
function initPool(config) {
  if (pool) return pool;

  pool = new Pool({
    host: config.PGHOST || process.env.PGHOST || 'localhost',
    port: parseInt(config.PGPORT || process.env.PGPORT || '5432', 10),
    database: config.PGDATABASE || process.env.PGDATABASE || 'spacefractions',
    user: config.PGUSER || process.env.PGUSER || 'spacefractions',
    password: config.PGPASSWORD || process.env.PGPASSWORD || 'spacefractions',
    max: 20,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000
  });

  pool.on('error', (err) => {
    console.error('Unexpected PostgreSQL pool error:', err);
  });

  return pool;
}

/**
 * Get the current pool instance.
 */
function getPool() {
  if (!pool) {
    throw new Error('Database pool not initialized. Call initPool() first.');
  }
  return pool;
}

/**
 * Execute a query with params.
 */
async function query(sql, params) {
  const client = await getPool().connect();
  try {
    const result = await client.query(sql, params);
    return result;
  } finally {
    client.release();
  }
}

/**
 * Execute a query and return a single row or null.
 */
async function queryOne(sql, params) {
  const result = await query(sql, params);
  return result.rows[0] || null;
}

/**
 * Run `fn(client)` inside a PostgreSQL transaction on a single dedicated
 * client. `client` supports `query` and `queryOne` (single-row helper).
 * Commits on success, rolls back on error. Releases the client to the pool
 * in all cases.
 *
 * @param {(client: {query: Function, queryOne: Function}) => Promise<any>} fn
 * @returns {Promise<any>} fn's return value
 */
async function withTransaction(fn) {
  const client = await getPool().connect();
  try {
    await client.query('BEGIN');
    const txClient = {
      query: (sql, params) => client.query(sql, params),
      queryOne: async (sql, params) => {
        const r = await client.query(sql, params);
        return r.rows[0] || null;
      }
    };
    let result;
    try {
      result = await fn(txClient);
      await client.query('COMMIT');
      return result;
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }
  } finally {
    client.release();
  }
}

/**
 * Run a migration from a SQL string on a single owned client inside a
 * transaction with proper rollback on error.
 *
 * The SQL content may contain arbitrary statements (multi-statement `DO $$`
 * blocks, `BEGIN`/`COMMIT` wrappers, etc.) that cannot be safely split on
 * semicolons. We execute the whole content in one `client.query()` call,
 * which runs it on a single connection.
 *
 * A given migration name is recorded in `_schema_migrations`; if it was
 * already applied we skip running it again, making repeated startup
 * (including concurrent startup of multiple services) safe and idempotent.
 *
 * @param {string} sqlContent - raw SQL migration text
 * @param {string} [name='migration'] - stable identifier for this migration
 */
async function runMigrations(sqlContent, name = 'migration') {
  const client = await getPool().connect();
  try {
    // Ensure the tracking table exists before recording/applying.
    await client.query(
      'CREATE TABLE IF NOT EXISTS _schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW())'
    );

    const applied = await client.query(
      'SELECT 1 FROM _schema_migrations WHERE name = $1',
      [name]
    );
    if (applied.rowCount > 0) {
      return { applied: false, name };
    }

    await client.query('BEGIN');
    try {
      // Run the full migration as one unit on this client. The script's own
      // BEGIN/COMMIT (if present) is nested implicitly; Postgres treats
      // nested BEGIN as a warning and the outer transaction governs.
      await client.query(sqlContent);
      await client.query(
        'INSERT INTO _schema_migrations (name) VALUES ($1)',
        [name]
      );
      await client.query('COMMIT');
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }

    return { applied: true, name };
  } finally {
    client.release();
  }
}

/**
 * Health check: can we connect to the database?
 */
async function healthCheck() {
  try {
    await query('SELECT 1');
    return true;
  } catch (err) {
    console.error('Database health check failed:', err.message);
    return false;
  }
}

/**
 * Close the pool.
 */
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

module.exports = {
  initPool,
  getPool,
  query,
  queryOne,
  withTransaction,
  runMigrations,
  healthCheck,
  closePool
};

/**
 * Game Service – Entry Point
 *
 * Internal service listening on GAME_SERVICE_PORT (default 3001).
 * Not exposed to browsers directly; gateway proxies requests.
 */

const express = require('express');
const { initPool, runMigrations, closePool, healthCheck } = require('@spacefractions/shared/db');
const { initCache, closeCache } = require('@spacefractions/shared/cache');
const { initMQ, closeMQ } = require('@spacefractions/shared/mq');
const { configure: configureAuth } = require('@spacefractions/shared/auth');
const { errorHandler } = require('@spacefractions/shared/errors');
const { metricsMiddleware, getMetrics, getContentType } = require('@spacefractions/shared/metrics');

const routes = require('./routes');
const fs = require('fs');
const path = require('path');

const PORT = parseInt(process.env.GAME_SERVICE_PORT || '3001', 10);
const METRICS_PORT = parseInt(process.env.GAME_METRICS_PORT || '9091', 10);

async function main() {
  // Initialize infrastructure
  configureAuth({});
  await initPool({});
  await initCache({});
  try { await initMQ({}); } catch { /* non-critical */ }

  // Run migrations
  try {
    const sql = fs.readFileSync(
      path.join(__dirname, '..', '..', '..', 'sql', '001_initial.sql'),
      'utf-8'
    );
    await runMigrations(sql, '001_initial');
    console.log('Game service: migrations applied');
  } catch (err) {
    console.warn('Game service: migration skipped (may already be applied):', err.message);
  }

  const app = express();
  app.use(express.json());
  app.use(metricsMiddleware);

  // Health check
  app.get('/health', async (_req, res) => {
    const dbOk = await healthCheck();
    res.status(dbOk ? 200 : 503).json({
      status: dbOk ? 'ok' : 'degraded',
      service: 'game-service',
      database: dbOk ? 'healthy' : 'unhealthy'
    });
  });

  // API routes (mounted under /api/games by gateway, but also available directly)
  app.use('/api/games', routes);

  // Error handler
  app.use(errorHandler);

  // Start main server
  app.listen(PORT, () => {
    console.log(`Game service listening on port ${PORT}`);
  });

  // Metrics server (separate port)
  const metricsApp = express();
  metricsApp.get('/metrics', async (_req, res) => {
    res.set('Content-Type', getContentType());
    res.send(await getMetrics());
  });
  metricsApp.listen(METRICS_PORT, () => {
    console.log(`Game service metrics on port ${METRICS_PORT}`);
  });

  // Graceful shutdown
  const shutdown = async () => {
    console.log('Game service shutting down...');
    await closeCache();
    await closeMQ();
    await closePool();
    process.exit(0);
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

main().catch(err => {
  console.error('Game service failed to start:', err);
  process.exit(1);
});

