  ],
  "scripts": {
    "build": "node scripts/check-sources.js",
    "start": "echo 'Use compose.yaml to start all services. Gateway: node gateway/src/index.js'",
    "test": "node --test shared/test/*.test.js services/*/test/*.test.js",
    "test:integration": "node --test test/integration/*.test.js",
    "test:all": "node --test shared/test/*.test.js services/*/test/*.test.js test/integration/*.test.js",
    "lint": "node --check gateway/src/index.js"
  },
  "engines": {
    "node": ">=22.0.0"
  },
  "devDependencies": {
  }
}

/**
 * Game Service – HTTP Routes
 */

const { Router } = require('express');
const gameEngine = require('./game-engine');
const { requireAuth, requireAdmin, optionalAuth } = require('@spacefractions/shared/auth');
const { BadRequestError, NotFoundError } = require('@spacefractions/shared/errors');
const { gamesCreated, answersSubmitted, activeGames } = require('@spacefractions/shared/metrics');
const { publishScoreUpdated } = require('@spacefractions/shared/mq');
const { get, set } = require('@spacefractions/shared/cache');
const { query } = require('@spacefractions/shared/db');
const { resolveInternalUserId } = require('@spacefractions/shared/identity');

const router = Router();

/**
 * POST /api/games
 * Create a new game. Requires authentication.
 * Body (optional): { questionIds: [id, ...] }
 */
router.post('/', requireAuth, async (req, res, next) => {
  try {
    const userId = await getUserId(req.user);
    const questionIds = req.body?.questionIds || null;

    const game = await gameEngine.createGame(userId, questionIds);

    // Fetch questions WITHOUT correctAnswer
    const questions = await Promise.all(
      game.question_ids.map(async (qId) => {
        const q = await require('@spacefractions/shared/db').queryOne(
          'SELECT id, prompt, options FROM questions WHERE id = $1',
          [qId]
        );
        return q;
      })
    );

    gamesCreated.inc();
    activeGames.inc();

    // Cache the game
    await set(`game:${game.id}`, game, 1800);

    res.status(201).json({
      id: game.id,
      state: game.state,
      questions: questions.filter(Boolean),
      currentQuestionIndex: game.current_question_index
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/games/:id
 * Get game state. Only owner or admin can access.
 * Never includes correctAnswer.
 */
router.get('/:id', requireAuth, async (req, res, next) => {
  try {
    const userId = await getUserId(req.user);
    const isAdmin = isAdminUser(req.user);
    const gameId = parseInt(req.params.id, 10);

    // Try cache first
    let game = await get(`game:${gameId}`);
    if (!game) {
      game = await gameEngine.getGame(gameId, userId, isAdmin);
      await set(`game:${gameId}`, game, 1800);
    } else {
      // Verify ownership
      if (!isAdmin && game.user_id !== userId) {
        return next(new NotFoundError('Game not found'));
      }
    }

    // Get questions without correctAnswer
    const questions = await Promise.all(
      game.question_ids.map(async (qId) => {
        const q = await require('@spacefractions/shared/db').queryOne(
          'SELECT id, prompt, options FROM questions WHERE id = $1',
          [qId]
        );
        return q;
      })
    );

    res.json({
      id: game.id,
      state: game.state,
      score: game.score,
      questions: questions.filter(Boolean),
      currentQuestionIndex: game.current_question_index,
      totalQuestions: game.question_ids.length,
      createdAt: game.created_at,
      updatedAt: game.updated_at
    });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/games/:id/pause
 * Pause the game. Owner only.
 */
router.post('/:id/pause', requireAuth, async (req, res, next) => {
  try {
    const userId = await getUserId(req.user);
    const isAdmin = isAdminUser(req.user);
    const gameId = parseInt(req.params.id, 10);

    // Verify ownership
    await gameEngine.getGame(gameId, userId, isAdmin);

    const game = await gameEngine.pauseGame(gameId);
    await set(`game:${gameId}`, game, 1800);

    res.json({ id: game.id, state: game.state });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/games/:id/resume
 * Resume the game. Owner only.
 */
router.post('/:id/resume', requireAuth, async (req, res, next) => {
  try {
    const userId = getUserId(req.user);
    const isAdmin = isAdminUser(req.user);
    const gameId = parseInt(req.params.id, 10);

    await gameEngine.getGame(gameId, userId, isAdmin);

    const game = await gameEngine.resumeGame(gameId);
    await set(`game:${gameId}`, game, 1800);

    res.json({ id: game.id, state: game.state });
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/games/:id/answers
 * Submit an answer. Owner only. Paused games return 409.
 */
router.post('/:id/answers', requireAuth, async (req, res, next) => {
  try {
    const userId = getUserId(req.user);
    const isAdmin = isAdminUser(req.user);
    const gameId = parseInt(req.params.id, 10);
    const { questionId, answer } = req.body;

    if (!questionId || answer === undefined) {
      throw new BadRequestError('questionId and answer are required');
    }

    await gameEngine.getGame(gameId, userId, isAdmin);

    const result = await gameEngine.submitAnswer(
      gameId, parseInt(questionId, 10), answer, userId, isAdmin,
      publishScoreUpdated
    );

    answersSubmitted.inc({ correct: result.correct ? 'true' : 'false' });

    // Clear cache
    await require('@spacefractions/shared/cache').del(`game:${gameId}`);

    res.json({
      correct: result.correct,
      score: result.score,
      gameState: result.gameState
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/games/:id/score
 * Get game score. Owner or admin only.
 */
router.get('/:id/score', requireAuth, async (req, res, next) => {
  try {
    const userId = getUserId(req.user);
    const isAdmin = isAdminUser(req.user);
    const gameId = parseInt(req.params.id, 10);

    // Verify ownership
    const game = await gameEngine.getGame(gameId, userId, isAdmin);

    res.json({ score: game.score, state: game.state });
  } catch (err) {
    next(err);
  }
});

/**
 * Helper: Extract internal user ID from OIDC token.
 * Looks up or creates user in the database.
 */
function getUserId(user) {
  // The user object from auth middleware has OIDC claims
  // We use sub as the stable identifier
  return user.sub;
}

/**
 * Helper: Check if the user has admin role.
 */
function isAdminUser(user) {
  const roles = user?.realm_access?.roles || [];
  return roles.includes('admin');
}

module.exports = router;

/**
 * Canonical OIDC subject -> internal `users.id` resolution.
 *
 * The `users` table owns the mapping from the OIDC `sub` claim (a stable,
 * provider-issued string, e.g. a Keycloak UUID) to a numeric internal id used
 * as the foreign key for game ownership (`games.user_id`) and question
 * authorship (`questions.created_by`).
 *
 * Every service that needs an internal numeric user id MUST resolve it through
 * this function (rather than relying on the raw `sub`), so that game-service,
 * user-service and admin-service all agree on the same identity mapping.
 *
 * The resolution is an idempotent upsert on the unique `sub` column: if a row
 * already exists it is loaded (and its username/email refreshed), otherwise a
 * new row is created. Concurrent callers are safe thanks to `ON CONFLICT`.
 */

const { query, queryOne } = require('./db');
const { BadRequestError } = require('./errors');

/**
 * Resolve and return the numeric internal `users.id` for an authenticated
 * caller's OIDC claims, creating the row on first sight (idempotent).
 *
 * @param {object} claims - decoded (and already verified) OIDC token payload.
 * @returns {Promise<number>} the numeric `users.id`.
 * @throws {BadRequestError} when the claims lack a `sub`.
 */
async function resolveInternalUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }

  const username =
    claims.preferred_username ||
    claims.email ||
    claims.name ||
    `user-${String(sub).slice(0, 8)}`;
  const email = claims.email || null;

  const existing = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  if (existing) {
    // Keep the human-readable fields fresh (best effort).
    await query(
      `UPDATE users SET username = $2, email = COALESCE($3, email) WHERE id = $1`,
      [existing.id, username, email]
    );
    return existing.id;
  }

  const result = await query(
    `INSERT INTO users (sub, username, email)
     VALUES ($1, $2, $3)
     ON CONFLICT (sub) DO UPDATE SET
       username = EXCLUDED.username,
       email = COALESCE(EXCLUDED.email, users.email)
     RETURNING id`,
    [sub, username, email]
  );

  return result.rows[0].id;
}

module.exports = { resolveInternalUserId };

/**
 * User Service – HTTP Routes
 *
 * Endpoints (mounted under /api/users by the gateway, also directly):
 *   GET  /api/users/me                     – current user profile (requires auth)
 *   GET  /api/users/oidec/callback         – OIDC redirect callback (token exchange helper)
 *   GET  /api/users/health                 – dependency health
 *
 * The user-service owns the mapping from OIDC `sub` to the internal
 * `users` row. It does NOT expose other users' data: only the caller's
 * own profile (authorized by `sub`), so cross-user enumeration is blocked.
 */

const { Router } = require('express');
const { requireAuth } = require('@spacefractions/shared/auth');
const { BadRequestError, NotFoundError } = require('@spacefractions/shared/errors');
const { query, queryOne, getPool } = require('@spacefractions/shared/db');
const { get, set } = require('@spacefractions/shared/cache');

const router = Router();

/**
 * Resolve (and lazily create) the internal user row for an OIDC payload.
 * Returns the canonitalized user record.
 */
async function resolveUser(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }

  const username =
    claims.preferred_username ||
    claims.email ||
    claims.name ||
    `user-${sub.slice(0, 8)}`;
  const email = claims.email || null;

  // Fast path: cached mapping sub -> user row.
  const cacheKey = `user:sub:${sub}`;
  const cached = await get(cacheKey);
  if (cached) {
    return cached;
  }

  // Insert-or-select the user row idempotently by unique `sub`.
  const existing = await queryOne('SELECT * FROM users WHERE sub = $1', [sub]);
  if (existing) {
    await set(cacheKey, existing, 300);
    return existing;
  }

  const result = await query(
    `INSERT INTO users (sub, username, email)
     VALUES ($1, $2, $3)
     ON CONFLICT (sub) DO UPDATE SET
       username = EXCLUDED.username,
       email = COALESCE(EXCLUDED.email, users.email)
     RETURNING *`,
    [sub, username, email]
  );

  const row = result.rows[0];
  await set(cacheKey, row, 300);
  return row;
}

/**
 * GET /api/users/me
 * Return the authenticated user's profile. The profile is keyed off the
 * OIDC `sub` claim, never off a client-supplied id, enforcing ownership.
 */
router.get('/me', requireAuth, async (req, res, next) => {
  try {
    const user = await resolveUser(req.user);

    // Public profile shape: never include internal sub beyond what the
    // client already knows about itself.
    res.json({
      id: user.id,
      username: user.username,
      email: user.email,
      createdAt: user.created_at
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/users/oidc/callback
 * OIDC authorization-code callback. In the Compose reference topology the
 * Keycloak client uses the "standard flow" redirect to the browser UI, so
 * this route is primarily a compatibility/extension point: it accepts an
 * authorization code (or an id_token), validates the token via the shared
 * OIDC validator, and returns the profile that results after resolution.
 *
 * NOTE: token validation here leverages shared/auth.validateToken, which
 * enforces issuer/audience/expiration. No client secret ever leaves the
 * server; placeholders only in configuration.
 */
router.get('/oidc/callback', async (req, res, next) => {
  try {
    const token = req.query.id_token || req.query.access_token;
    if (!token) {
      throw new BadRequestError('Missing id_token or access_token');
    }

    const { validateToken } = require('@spacefractions/shared/auth');
    const claims = await validateToken(token);
    const user = await resolveUser(claims);

    res.json({
      id: user.id,
      username: user.username,
      email: user.email,
      subject: claims.sub
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/users/:id
 * Look up a specific user by internal id. Restricted to the caller's own
 * id (from a validated token); any attempt to read another user's profile
 * returns 404 (indistinguishable from nonexistence), satisfying the
 * "other users' data -> 403/404" contract requirement.
 */
router.get('/:id', requireAuth, async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid user id');
    }

    // The caller may only address their own profile.
    const self = await resolveUser(req.user);
    if (self.id !== id) {
      throw new NotFoundError('User not found');
    }

    res.json({
      id: self.id,
      username: self.username,
      email: self.email,
      createdAt: self.created_at
    });
  } catch (err) {
    next(err);
  }
});

module.exports = router;

/**
 * Admin Service – HTTP Routes
 *
 * Authenticated administrator-only question CRUD. Mounted under
 * /api/admin by the gateway (and directly on this service).
 *
 *   POST   /api/admin/questions            – create question (201)
 *   GET    /api/admin/questions            – list questions (includes correct_answer)
 *   GET    /api/admin/questions/:id        – single question (includes correct_answer)
 *   PUT    /api/admin/questions/:id        – update question
 *   DELETE /api/admin/questions/:id        – delete question (204)
 *
 * Authorization: every route requires a valid Bearer OIDC access token AND
 * the `admin` realm role. Unauthenticated requests yield 401; authenticated
 * non-admin requests yield 403 (per the acceptance contract).
 *
 * Server-side validation:
 *   - prompt must be a non-empty string
 *   - options must be an array of 2..10 non-empty strings
 *   - correctAnswer must be a well-formed exact rational ("a/b" or integer)
 *   - correctAnswer must be one of options (the correct answer is always a
 *     listed option, matching the multiple-choice model)
 */

const { Router } = require('express');
const { requireAuth, requireAdmin } = require('@spacefractions/shared/auth');
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require('@spacefractions/shared/errors');
const { query, queryOne } = require('@spacefractions/shared/db');
const { isValidFraction, fractionsEqual, formatFraction } = require('@spacefractions/shared/fraction');
const { questionsCreated } = require('@spacefractions/shared/metrics');
const { indexQuestion, deleteQuestion: deleteQuestionDoc } = require('../../question-service/src/search');

const router = Router();

const LIMIT_MAX = 500;
const OPTIONS_MIN = 2;
const OPTIONS_MAX = 10;

/**
 * Normalize and validate a question payload ({ prompt, options, correctAnswer }).
 * Returns the normalized { prompt, options, correctAnswer } on success.
 * Throws BadRequestError for malformed input.
 */
function validateQuestionPayload(body) {
  if (typeof body !== 'object' || body === null) {
    throw new BadRequestError('Request body must be a JSON object');
  }

  const { prompt, options, correctAnswer } = body;

  // prompt: non-empty string with a length cap
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new BadRequestError('prompt must be a non-empty string');
  }
  if (prompt.length > 2000) {
    throw new BadRequestError('prompt exceeds maximum length of 2000 characters');
  }

  // options: array of 2..10 non-empty strings, no duplicates (after trim)
  if (!Array.isArray(options)) {
    throw new BadRequestError('options must be an array of strings');
  }
  if (options.length < OPTIONS_MIN || options.length > OPTIONS_MAX) {
    throw new BadRequestError(
      `options must contain between ${OPTIONS_MIN} and ${OPTIONS_MAX} strings`
    );
  }
  const seen = new Set();
  for (const opt of options) {
    if (typeof opt !== 'string' || opt.trim() === '') {
      throw new BadRequestError('each option must be a non-empty string');
    }
    if (opt.length > 200) {
      throw new BadRequestError('an option exceeds maximum length of 200 characters');
    }
    if (seen.has(opt.trim())) {
      throw new BadRequestError('options must not contain duplicates');
    }
    seen.add(opt.trim());
  }

  // correctAnswer: well-formed exact fraction AND one of the options
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new BadRequestError('correctAnswer must be a non-empty string');
  }
  if (!isValidFraction(correctAnswer)) {
    throw new BadRequestError(
      'correctAnswer must be a well-formed fraction ("a/b", denominator != 0)'
    );
  }
  // The correct answer must appear among the options (compare as exact
  // rationals so "1/2" and "2/4" are considered the same answer).
  const normalizedCorrect = formatFraction(correctAnswer);
  const optionMatches = options.some((opt) => fractionsEqual(opt, correctAnswer));
  if (!optionMatches) {
    throw new BadRequestError('correctAnswer must be one of the provided options');
  }

  return {
    prompt: prompt.trim(),
    options,
    correctAnswer: normalizedCorrect,
  };
}

/**
 * Serialize a question row for admin responses (includes correct_answer).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: row.options,
    correctAnswer: row.correct_answer,
    createdBy: row.created_by,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/**
 * Resolve the internal user id for the authenticated caller (from OIDC `sub`).
 * Used to stamp `created_by` on new questions and to authorize ownership.
 */
async function resolveCallerUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }
  const row = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  return row ? row.id : null;
}

// Apply auth middlewares to all admin routes. Order matters: requireAuth
// populates req.user, then requireAdmin enforces the realm role.
router.use(requireAuth, requireAdmin);

/**
 * GET /api/admin/questions
 * List all questions (with correct_answer), newest first. Optional ?limit.
 */
router.get('/questions', async (req, res, next) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : LIMIT_MAX;
    if (Number.isNaN(limit) || limit < 1 || limit > LIMIT_MAX) {
      throw new BadRequestError(`limit must be between 1 and ${LIMIT_MAX}`);
    }

    const result = await query(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions
       ORDER BY created_at DESC
       LIMIT $1`,
      [limit]
    );

    res.json({
      questions: result.rows.map(toAdminQuestion),
      count: result.rows.length,
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/admin/questions/:id
 * Single question (with correct_answer).
 */
router.get('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const row = await queryOne(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions WHERE id = $1`,
      [id]
    );

    if (!row) {
      throw new NotFoundError('Question not found');
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/admin/questions
 * Create a question. Body: { prompt, options: [string], correctAnswer }.
 * Returns 201 with the created question.
 */
router.post('/questions', async (req, res, next) => {
  try {
    const normalized = validateQuestionPayload(req.body);
    const createdBy = await resolveCallerUserId(req.user);

    const result = await query(
      `INSERT INTO questions (prompt, options, correct_answer, created_by)
       VALUES ($1, $2, $3, $4)
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
        createdBy,
      ]
    );

    const row = result.rows[0];

    // Best-effort Elasticsearch indexing (non-fatal).
    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    questionsCreated.inc();

    res.status(201).json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * PUT /api/admin/questions/:id
 * Update (replace) a question. Same validation as create.
 */
router.put('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const existing = await queryOne('SELECT id FROM questions WHERE id = $1', [id]);
    if (!existing) {
      throw new NotFoundError('Question not found');
    }

    const normalized = validateQuestionPayload(req.body);

    const result = await query(
      `UPDATE questions
       SET prompt = $2, options = $3, correct_answer = $4, updated_at = NOW()
       WHERE id = $1
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        id,
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
      ]
    );

    const row = result.rows[0];

    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /api/admin/questions/:id
 * Delete a question. Returns 204 No Content on success.
 */
router.delete('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const result = await query('DELETE FROM questions WHERE id = $1 RETURNING id', [id]);

    if (result.rows.length === 0) {
      throw new NotFoundError('Question not found');
    }

    try {
      await deleteQuestionDoc(id);
    } catch (err) {
      console.warn('Admin service: delete question doc failed:', err.message);
    }

    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
module.exports.validateQuestionPayload = validateQuestionPayload;
module.exports.toAdminQuestion = toAdminQuestion;

/**
 * Game Engine – core game logic for Space Fractions.
 *
 * States: 'playing', 'paused', 'completed'
 * Transitions:
 *   playing  -> paused   (pause)
 *   paused   -> playing  (resume)
 *   playing  -> completed (all questions answered)
 *
 * Scoring:
 *   - Each correct answer to a not-yet-correctly-answered question: +1
 *   - Re-answering correctly: idempotent (no score change)
 *   - Score never decreases
 */

const { query, queryOne, withTransaction } = require('@spacefractions/shared/db');
const { fractionsEqual, isValidFraction } = require('@spacefractions/shared/fraction');
const { BadRequestError, ConflictError, NotFoundError } = require('@spacefractions/shared/errors');

/**
 * Create a new game for the given user with the specified questions.
 */
async function createGame(userId, questionIds) {
  // If no question IDs provided, fetch all available questions
  if (!questionIds || questionIds.length === 0) {
    const result = await query('SELECT id FROM questions ORDER BY created_at');
    questionIds = result.rows.map(r => r.id);
  }

  if (questionIds.length === 0) {
    throw new BadRequestError('No questions available to create a game');
  }

  const result = await query(
    `INSERT INTO games (user_id, state, score, question_ids, current_question_index)
     VALUES ($1, 'playing', 0, $2, 0)
     RETURNING *`,
    [userId, questionIds]
  );

  return result.rows[0];
}

/**
 * Get a game by ID. Validates ownership (unless isAdmin).
 */
async function getGame(gameId, userId, isAdmin) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) {
    throw new NotFoundError('Game not found');
  }

  // Authorization: only owner or admin can access
  if (!isAdmin && game.user_id !== userId) {
    throw new NotFoundError('Game not found');
  }

  return game;
}

/**
 * Get the current question for a game.
 */
async function getCurrentQuestion(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'completed') {
    return null;
  }

  const idx = game.current_question_index;
  if (idx >= game.question_ids.length) {
    return null;
  }

  const qId = game.question_ids[idx];
  const question = await queryOne(
    'SELECT id, prompt, options FROM questions WHERE id = $1',
    [qId]
  );

  return question;
}

/**
 * Pause a game. Only valid from 'playing' state.
 */
async function pauseGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'paused') {
    // Already paused – idempotent
    return game;
  }

  if (game.state !== 'playing') {
    throw new ConflictError(`Cannot pause game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'paused', updated_at = NOW()
     WHERE id = $1 AND state = 'playing'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Resume a game. Only valid from 'paused' state.
 */
async function resumeGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'playing') {
    // Already playing – idempotent
    return game;
  }

  if (game.state !== 'paused') {
    throw new ConflictError(`Cannot resume game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'playing', updated_at = NOW()
     WHERE id = $1 AND state = 'paused'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Submit an answer for a question in a game.
 * Returns { correct, score, gameState }.
 *
 * Idempotent: re-answering the same question never increases score a second
 * time, because the score increment is gated on the atomic `scored`
 * FALSE -> TRUE transition of the single answer row (guarded by the
 * UNIQUE (game_id, question_id) constraint and a row lock on the game).
 *
 * Concurrency: the whole mutation runs in one transaction holding a
 * `SELECT ... FOR UPDATE` lock on the game row, so two concurrent duplicate
 * submissions of the same question are serialized and only the first sees
 * `scored = FALSE`, preventing double increments.
 */
async function submitAnswer(gameId, questionId, answer, userId, isAdmin, publishScoreEvent) {
  // Basic validation outside the transaction: a malformed fraction or an
  // out-of-game question cannot possibly score.
  if (!isValidFraction(answer)) {
    throw new BadRequestError('Malformed fraction answer');
  }

  return withTransaction(async (tx) => {
    // Lock the game row for the duration of the transaction. This serializes
    // concurrent submissions against the same game and (re)checks ownership,
    // pause and completion state atomically with the score mutation.
    const game = await tx.queryOne(
      'SELECT * FROM games WHERE id = $1 FOR UPDATE',
      [gameId]
    );
    if (!game) {
      throw new NotFoundError('Game not found');
    }
    if (!isAdmin && game.user_id !== userId) {
      throw new NotFoundError('Game not found');
    }

    if (game.state === 'paused') {
      throw new ConflictError('Cannot answer while game is paused');
    }

    // The question must actually belong to this game.
    if (!game.question_ids.includes(questionId)) {
      throw new BadRequestError('Question is not part of this game');
    }

    // Resolve the correct answer.
    const question = await tx.queryOne(
      'SELECT id, correct_answer FROM questions WHERE id = $1',
      [questionId]
    );
    if (!question) {
      throw new NotFoundError('Question not found');
    }

    const correct = fractionsEqual(answer, question.correct_answer);

    // Determine whether this question is the currently-advanced one so we can
    // move progress forward exactly once (see below).
    const isCurrentQuestion =
      game.current_question_index < game.question_ids.length &&
      questionId === game.question_ids[game.current_question_index];

    const newIdx = game.current_question_index;
    const completed = newIdx >= game.question_ids.length;

    // Completed games: only an idempotent replay of an already-scored
    // question is permitted (returns current score without error).
    if (game.state === 'completed' || completed) {
      const replayed = await tx.queryOne(
        'SELECT scored FROM game_answers WHERE game_id = $1 AND question_id = $2',
        [gameId, questionId]
      );
      if (replayed && replayed.scored) {
        return { correct: true, score: game.score, gameState: 'completed' };
      }
      throw new ConflictError('Game is already completed');
    }

    // Atomic answer upsert + score gate. The `scored` column flips from FALSE
    // to TRUE only when this row is first marked correct. Because INSERT ...
    // ON CONFLICT is a single atomic statement guarded by the unique
    // constraint (and the FOR UPDATE lock prevents concurrent writers on this
    // game), exactly one submission observes `scored = EXCLUDED.scored` being a
    // FALSE -> TRUE transition and increments the score by 1. All others see
    // no transition (scored stays FALSE for a wrong answer, or stays TRUE for
    // a repeated correct answer), so the score is never double-counted.
    const upsert = await tx.query(
      `INSERT INTO game_answers (game_id, question_id, answer, correct, scored)
       VALUES ($1, $2, $3, $4, $4)
       ON CONFLICT (game_id, question_id) DO UPDATE SET
         answer = EXCLUDED.answer,
         correct = EXCLUDED.correct,
         scored = CASE
           WHEN game_answers.scored = FALSE AND EXCLUDED.scored = TRUE THEN TRUE
           ELSE game_answers.scored
         END
       RETURNING (
         CASE
           WHEN game_answers.scored = FALSE AND EXCLUDED.scored = TRUE THEN TRUE
           ELSE FALSE
         END
       ) AS newly_scored`,
      [gameId, questionId, answer, correct]
    );

    const newlyScored = upsert.rows[0] && upsert.rows[0].newly_scored === true;

    // Apply the score increment and, when this is the current question,
    // advance progress — all within the same transaction as the lock.
    let finalScore = game.score;
    let finalState = game.state;
    let finalIdx = game.current_question_index;

    if (newlyScored) {
      const sc = await tx.query(
        `UPDATE games SET score = score + 1, updated_at = NOW()
         WHERE id = $1 RETURNING score`,
        [gameId]
      );
      finalScore = numberScore(sc.rows[0].score);
    }

    // Advance progress once, only when answering the current question, and
    // only if not already advanced for this question (the unique answer row
    // already prevents re-advancement for scored questions, but a wrong
    // answer to the current question should also advance progress exactly once
    // per distinct question — enforced by the unique answer-row upsert gate).
    if (isCurrentQuestion) {
      const advanced = await tx.query(
        `UPDATE games
         SET current_question_index = $1,
             state = CASE WHEN $1 >= array_length(question_ids, 1) THEN 'completed' ELSE state END,
             updated_at = NOW()
         WHERE id = $2
         RETURNING current_question_index, state`,
        [game.current_question_index + 1, gameId]
      );
      finalIdx = advanced.rows[0].current_question_index;
      finalState = advanced.rows[0].state;
    }

    if (newlyScored && publishScoreEvent) {
      try {
        publishScoreEvent(gameId, userId, finalScore, questionId);
      } catch {
        // Non-critical; do not fail the transaction over telemetry.
      }
    }

    return {
      correct,
      score: finalScore,
      gameState: finalState
    };
  });
}

function numberScore(v) {
  return typeof v === 'number' ? v : parseInt(v, 10);
}

/**
 * Get the score for a game.
 */
async function getScore(gameId) {
  const game = await queryOne('SELECT id, score, state FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');
  return { score: game.score, state: game.state };
}

module.exports = {
  createGame,
  getGame,
  getCurrentQuestion,
  pauseGame,
  resumeGame,
  submitAnswer,
  getScore
};

/**
 * PostgreSQL database pool and query helpers.
 */

const { Pool } = require('pg');

let pool = null;

/**
 * Initialize the database pool.
 */
function initPool(config) {
  if (pool) return pool;

  pool = new Pool({
    host: config.PGHOST || process.env.PGHOST || 'localhost',
    port: parseInt(config.PGPORT || process.env.PGPORT || '5432', 10),
    database: config.PGDATABASE || process.env.PGDATABASE || 'spacefractions',
    user: config.PGUSER || process.env.PGUSER || 'spacefractions',
    password: config.PGPASSWORD || process.env.PGPASSWORD || 'spacefractions',
    max: 20,
    idleTimeoutMillis: 30_000,
    connectionTimeoutMillis: 5_000
  });

  pool.on('error', (err) => {
    console.error('Unexpected PostgreSQL pool error:', err);
  });

  return pool;
}

/**
 * Get the current pool instance.
 */
function getPool() {
  if (!pool) {
    throw new Error('Database pool not initialized. Call initPool() first.');
  }
  return pool;
}

/**
 * Execute a query with params.
 */
async function query(sql, params) {
  const client = await getPool().connect();
  try {
    const result = await client.query(sql, params);
    return result;
  } finally {
    client.release();
  }
}

/**
 * Execute a query and return a single row or null.
 */
async function queryOne(sql, params) {
  const result = await query(sql, params);
  return result.rows[0] || null;
}

/**
 * Run `fn(client)` inside a PostgreSQL transaction on a single dedicated
 * client. `client` supports `query` and `queryOne` (single-row helper).
 * Commits on success, rolls back on error. Releases the client to the pool
 * in all cases.
 *
 * @param {(client: {query: Function, queryOne: Function}) => Promise<any>} fn
 * @returns {Promise<any>} fn's return value
 */
async function withTransaction(fn) {
  const client = await getPool().connect();
  try {
    await client.query('BEGIN');
    const txClient = {
      query: (sql, params) => client.query(sql, params),
      queryOne: async (sql, params) => {
        const r = await client.query(sql, params);
        return r.rows[0] || null;
      }
    };
    let result;
    try {
      result = await fn(txClient);
      await client.query('COMMIT');
      return result;
    } catch (err) {
      await client.query('ROLLBACK');
      throw err;
    }
  } finally {
    client.release();
  }
}

/**
 * Strip leading/trailing whitespace and, when the whole script is wrapped
 * in an explicit `BEGIN;` / `COMMIT;` pair, remove that wrapper so the
 * migration can be executed inside our own transaction. This avoids nested
 * `BEGIN` (which PostgreSQL treats as a warning) and keeps a single,
 * well-defined transaction boundary owned by runMigrations.
 */
function unwrapExplicitTransaction(sqlContent) {
  let sql = String(sqlContent || '').trim();
  if (!sql) return sql;
  if (/^BEGIN\s*;?\s*$/i.test(sql)) {
    // unlikely leading BEGIN on its own first line; handled by regex below
  }
  const beginMatch = /^BEGIN\s*;?\s*(?:\r?\n|$)/i;
  const endMatch = /\bCOMMIT\s*;?\s*$/i;
  let start = sql;
  if (beginMatch.test(sql) && endMatch.test(sql)) {
    // Remove the leading BEGIN and trailing COMMIT.
    sql = sql.replace(beginMatch, '');
    sql = sql.replace(endMatch, '');
    sql = sql.trim();
    // If a trailing semicolon was left dangling after COMMIT removal, trim it.
    sql = sql.replace(/;\s*$/, '');
    sql = sql.trim();
  }
  return sql;
}

/**
 * Run a migration from a SQL string on a single owned client inside a
 * transaction with proper rollback on error.
 *
 * The SQL content may contain arbitrary statements (multi-statement `DO $$`
 * blocks, etc.) that cannot be safely split on semicolons. We execute the
 * whole (possibly unwrapped) content in one `client.query()` call on a
 * single connection.
 *
 * Robustness guarantees:
 * - A single owned client is borrowed and released in a finally block.
 * - The migration and its `_schema_migrations` record insert happen in one
 *   transaction; any error rolls back fully, leaving no partial state.
 * - A PostgreSQL advisory lock (`pg_advisory_xact_lock`) serializes
 *   concurrent service startups so two processes cannot both try to apply
 *   the same migration simultaneously.
 * - If the migration was already applied (per `_schema_migrations`), we skip
 *   running it again, making repeated startup safe and idempotent.
 *
 * @param {string} sqlContent - raw SQL migration text
 * @param {string} [name='migration'] - stable identifier for this migration
 */
async function runMigrations(sqlContent, name = 'migration') {
  const script = unwrapExplicitTransaction(sqlContent);
  const client = await getPool().connect();
  let released = false;
  try {
    // Serialize migrations across concurrent processes/connections. The lock
    // is transaction-scoped: it is released automatically at COMMIT/ROLLBACK.
    // Use a deterministic 64-bit key derived from the migration name.
    const lockKey = hashStringToInt64(name);

    await client.query('BEGIN');
    try {
      await client.query('SELECT pg_advisory_xact_lock($1)', [lockKey]);

      // Ensure the tracking table exists before recording/applying.
      await client.query(
        'CREATE TABLE IF NOT EXISTS _schema_migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT NOW())'
      );

      const applied = await client.query(
        'SELECT 1 FROM _schema_migrations WHERE name = $1',
        [name]
      );
      if (applied.rowCount === 0) {
        // Run the full migration as one unit on this client.
        if (script) {
          await client.query(script);
        }
        await client.query(
          'INSERT INTO _schema_migrations (name) VALUES ($1)',
          [name]
        );
      }

      await client.query('COMMIT');
      return { applied: applied.rowCount === 0, name };
    } catch (err) {
      try { await client.query('ROLLBACK'); } catch (_) { /* ignore */ }
      throw err;
    }
  } finally {
    if (!released) {
      released = true;
      client.release();
    }
  }
}

/**
 * Deterministic FNV-1a hash of a string reduced to a signed 64-bit integer
 * (BigInt), suitable for pg_advisory_xact_lock's bigint argument.
 */
function hashStringToInt64(str) {
  const s = String(str);
  let h = 0xcbf29ce484222325n; // FNV offset basis (64-bit)
  const prime = 0x100000001b3n; // FNV prime (64-bit)
  for (let i = 0; i < s.length; i++) {
    h ^= BigInt(s.charCodeAt(i));
    h = (h * prime) & 0xffffffffffffffffn;
  }
  // Interpret as signed 64-bit (two's complement) for pg bigint range.
  if (h > 0x7fffffffffffffffn) {
    h = h - 0x10000000000000000n;
  }
  return h.toString();
}

/**
 * Health check: can we connect to the database?
 */
async function healthCheck() {
  try {
    await query('SELECT 1');
    return true;
  } catch (err) {
    console.error('Database health check failed:', err.message);
    return false;
  }
}

/**
 * Close the pool.
 */
async function closePool() {
  if (pool) {
    await pool.end();
    pool = null;
  }
}

module.exports = {
  initPool,
  getPool,
  query,
  queryOne,
  withTransaction,
  runMigrations,
  healthCheck,
  closePool
};

