/**
 * Gateway – Entry Point
 *
 * Single entrypoint for the Space Fractions system, listening on port 3000.
 *
 * Responsibilities:
 *   - serve the browser UI from gateway/public (/) 
 *   - forward /api/* to the four internal services with bounded timeouts
 *   - expose /health (liveness) and /health/ready (aggregated readiness)
 *   - expose Prometheus metrics on a dedicated port (default 9095)
 *   - serve the OpenAPI spec at /openapi.yaml
 *
 * This process does NOT own game/question/user data; each downstream service
 * remains the authoritative owner and returns structured AppError payloads
 * that the gateway relays untouched.
 */

const express = require('express');
const path = require('path');
const { applyGatewayMiddleware } = require('./middleware');
const { errorHandler } = require('@spacefractions/shared/errors');
const { configure: configureAuth } = require('@spacefractions/shared/auth');
const { getMetrics, getContentType } = require('@spacefractions/shared/metrics');
const routes = require('./routes');

const PORT = parseInt(process.env.PORT || '3000', 10);
const METRICS_PORT = parseInt(process.env.GATEWAY_METRICS_PORT || '9095', 10);

function main() {
  // Configure OIDC validation (issue/audience enforcement) for downstream
  // services; the gateway itself is mostly a passthrough but shares the same
  // claims semantics so it can add request-scoped context in the future.
  configureAuth({});

  const app = express();
  applyGatewayMiddleware(app);

  // Static browser UI. Served before the API routes so "/" resolves to
  // index.html and unknown non-/api paths fall through to the UI shell.
  const publicDir = path.join(__dirname, '..', 'public');
  app.use(express.static(publicDir));

  // API + meta routes.
  app.use(routes);

  // SPA fallback: any non-API GET returns the UI shell.
  app.get(/^\/(?!api\/|health|openapi).*/, (_req, res) => {
    res.sendFile(path.join(publicDir, 'index.html'));
  });

  // Central error handler (relays downstream AppError status/code/message).
  app.use(errorHandler);

  const server = app.listen(PORT, () => {
    console.log(`Gateway listening on port ${PORT}`);
  });

  // Metrics endpoint on a dedicated port (scraped by Prometheus).
  const metricsApp = express();
  metricsApp.get('/metrics', async (_req, res) => {
    res.set('Content-Type', getContentType());
    res.send(await getMetrics());
  });
  metricsApp.listen(METRICS_PORT, () => {
    console.log(`Gateway metrics on port ${METRICS_PORT}`);
  });

  // Graceful shutdown.
  const shutdown = () => {
    console.log('Gateway shutting down...');
    server.close(() => process.exit(0));
    setTimeout(() => process.exit(0), 5000).unref();
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

main();

/**
 * Game Service – Entry Point
 *
 * Internal service listening on GAME_SERVICE_PORT (default 3001).
 * Not exposed to browsers directly; gateway proxies requests.
 */

const express = require('express');
const { initPool, runMigrations, closePool, healthCheck } = require('@spacefractions/shared/db');
const { initCache, closeCache } = require('@spacefractions/shared/cache');
const { initMQ, closeMQ } = require('@spacefractions/shared/mq');
const { configure: configureAuth } = require('@spacefractions/shared/auth');
const { errorHandler } = require('@spacefractions/shared/errors');
const { metricsMiddleware, getMetrics, getContentType } = require('@spacefractions/shared/metrics');

const routes = require('./routes');
const fs = require('fs');
const path = require('path');

const PORT = parseInt(process.env.GAME_SERVICE_PORT || '3001', 10);
const METRICS_PORT = parseInt(process.env.GAME_METRICS_PORT || '9091', 10);

async function main() {
  // Initialize infrastructure
  configureAuth({});
  await initPool({});
  await initCache({});
  try { await initMQ({}); } catch { /* non-critical */ }

  // Run migrations
  try {
    const sql = fs.readFileSync(
      path.join(__dirname, '..', '..', '..', 'sql', '001_initial.sql'),
      'utf-8'
    );
    await runMigrations(sql, '001_initial');
    console.log('Game service: migrations applied');
  } catch (err) {
    console.warn('Game service: migration skipped (may already be applied):', err.message);
  }

  const app = express();
  app.use(express.json());
  app.use(metricsMiddleware);

  // Health check
  app.get('/health', async (_req, res) => {
    const dbOk = await healthCheck();
    res.status(dbOk ? 200 : 503).json({
      status: dbOk ? 'ok' : 'degraded',
      service: 'game-service',
      database: dbOk ? 'healthy' : 'unhealthy'
    });
  });

  // API routes (mounted under /api/games by gateway, but also available directly)
  app.use('/api/games', routes);

  // Error handler
  app.use(errorHandler);

  // Start main server
  app.listen(PORT, () => {
    console.log(`Game service listening on port ${PORT}`);
  });

  // Metrics server (separate port)
  const metricsApp = express();
  metricsApp.get('/metrics', async (_req, res) => {
    res.set('Content-Type', getContentType());
    res.send(await getMetrics());
  });
  metricsApp.listen(METRICS_PORT, () => {
    console.log(`Game service metrics on port ${METRICS_PORT}`);
  });

  // Graceful shutdown
  const shutdown = async () => {
    console.log('Game service shutting down...');
    await closeCache();
    await closeMQ();
    await closePool();
    process.exit(0);
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

main().catch(err => {
  console.error('Game service failed to start:', err);
  process.exit(1);
});

/**
 * User Service – Entry Point
 *
 * Internal service listening on USER_SERVICE_PORT (default 3004).
 * Not exposed to browsers directly; gateway proxies requests.
 * Responsible for user profile resolution and OIDC token helpers.
 */

const express = require('express');
const { initPool, runMigrations, closePool, healthCheck: dbHealth } = require('@spacefractions/shared/db');
const { initCache, closeCache, healthCheck: cacheHealth } = require('@spacefractions/shared/cache');
const { configure: configureAuth } = require('@spacefractions/shared/auth');
const { errorHandler } = require('@spacefractions/shared/errors');
const { metricsMiddleware, getMetrics, getContentType } = require('@spacefractions/shared/metrics');

const routes = require('./routes');

const fs = require('fs');
const path = require('path');

const PORT = parseInt(process.env.USER_SERVICE_PORT || '3004', 10);
const METRICS_PORT = parseInt(process.env.USER_METRICS_PORT || '9094', 10);

async function main() {
  // Configure OIDC validation (issuer/audience from environment).
  configureAuth({});

  // PostgreSQL is required; fail fast if unavailable.
  await initPool({});

  // Cache is best-effort; degrade gracefully on failure.
  try { await initCache({}); } catch (err) { console.warn('User service: Redis unavailable:', err.message); }

  // Run migrations (idempotent via IF NOT EXISTS).
  try {
    const sql = fs.readFileSync(
      path.join(__dirname, '..', '..', '..', 'sql', '001_initial.sql'),
      'utf-8'
    );
    await runMigrations(sql);
    console.log('User service: migrations applied');
  } catch (err) {
    console.warn('User service: migration skipped:', err.message);
  }

  const app = express();
  app.use(express.json());
  app.use(metricsMiddleware);

  // Health check
  app.get('/health', async (_req, res) => {
    const dbOk = await dbHealth();
    const cacheOk = await cacheHealth();
    res.status(200).json({
      status: 'ok',
      service: 'user-service',
      database: dbOk ? 'healthy' : 'unhealthy',
      cache: cacheOk ? 'healthy' : 'unavailable'
    });
  });

  // API routes (mounted under /api/users by gateway, also available directly)
  app.use('/api/users', routes);

  // Error handler
  app.use(errorHandler);

  // Start main server
  app.listen(PORT, () => {
    console.log(`User service listening on port ${PORT}`);
  });

  // Metrics server (separate port)
  const metricsApp = express();
  metricsApp.get('/metrics', async (_req, res) => {
    res.set('Content-Type', getContentType());
    res.send(await getMetrics());
  });
  metricsApp.listen(METRICS_PORT, () => {
    console.log(`User service metrics on port ${METRICS_PORT}`);
  });

  // Graceful shutdown
  const shutdown = async () => {
    console.log('User service shutting down...');
    await closeCache();
    await closePool();
    process.exit(0);
  };
  process.on('SIGTERM', shutdown);
  process.on('SIGINT', shutdown);
}

main().catch(err => {
  console.error('User service failed to start:', err);
  process.exit(1);
});

/**
 * api.js – thin API client for the Space Fractions gateway.
 *
 * All requests go to the single gateway entrypoint (port 3000) using
 * relative paths, so the UI works identically behind any reverse proxy.
 * The Bearer access token is read from localStorage on every request.
 *
 * No correct answers are ever requested from (or surfaced by) the player
 * API; the UI only ever receives { id, prompt, options } per question.
 */

const TOKEN_KEY = 'spacefractions.token';

/* ------------------------------------------------------------------ *
 * Token helpers
 * ------------------------------------------------------------------ */

function getToken() {
  return localStorage.getItem(TOKEN_KEY) || null;
}

function setToken(token) {
  if (token) {
    localStorage.setItem(TOKEN_KEY, token);
  } else {
    localStorage.removeItem(TOKEN_KEY);
  }
}

function hasToken() {
  return Boolean(getToken());
}

/**
 * Decode a JWT payload (unverified) only to surface the subject/roles
 * in the UI. Never used for authorization decisions server-side.
 */
function decodeTokenPayload(token) {
  if (!token) return null;
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    const payload = parts[1].replace(/-/g, '+').replace(/_/g, '/');
    const padded = payload + '==='.slice(0, (4 - (payload.length % 4)) % 4);
    return JSON.parse(atob(padded));
  } catch {
    return null;
  }
}

function currentClaims() {
  return decodeTokenPayload(getToken());
}

function isAdmin() {
  const claims = currentClaims();
  const roles = claims?.realm_access?.roles || [];
  return roles.includes('admin');
}

function currentSubject() {
  const claims = currentClaims();
  return claims?.sub || null;
}

function preferredName() {
  const claims = currentClaims();
  return claims?.preferred_username || claims?.email || claims?.name || null;
}

/* ------------------------------------------------------------------ *
 * Request helper
 * ------------------------------------------------------------------ */

class ApiError extends Error {
  constructor(status, code, message) {
    super(message || code || `HTTP ${status}`);
    this.status = status;
    this.code = code;
  }
}

/**
 * Core fetch wrapper. Adds JSON + Authorization headers, parses JSON,
 * and throws a typed ApiError with the server's code/message if present.
 */
async function request(path, options = {}) {
  const headers = {
    'Content-Type': 'application/json',
    ...(options.headers || {})
  };
  const token = getToken();
  if (token) {
    headers['Authorization'] = `Bearer ${token}`;
  }

  const resp = await fetch(path, {
    method: options.method || 'GET',
    headers,
    body: options.body !== undefined ? JSON.stringify(options.body) : undefined
  });

  let data = null;
  if (resp.status !== 204) {
    const text = await resp.text();
    if (text) {
      try {
        data = JSON.parse(text);
      } catch {
        data = { message: text };
      }
    }
  }

  if (!resp.ok) {
    const err = data && (data.error || data.message)
      ? { code: data.code || data.error, message: data.message || data.error }
      : null;
    throw new ApiError(
      resp.status,
      err ? err.code : undefined,
      err ? err.message : `Request failed with status ${resp.status}`
    );
  }

  return data;
}

/* ------------------------------------------------------------------ *
 * Game endpoints
 * ------------------------------------------------------------------ */

/**
 * Create a new game. Optionally pass { questionIds: [id, ...] } for
 * reproducible practice. Returns the 201 body (id, state, questions).
 */
function createGame(questionIds) {
  const body = {};
  if (Array.isArray(questionIds) && questionIds.length > 0) {
    body.questionIds = questionIds;
  }
  return request('/api/games', { method: 'POST', body });
}

function getGame(id) {
  return request(`/api/games/${id}`);
}

function pauseGame(id) {
  return request(`/api/games/${id}/pause`, { method: 'POST', body: {} });
}

function resumeGame(id) {
  return request(`/api/games/${id}/resume`, { method: 'POST', body: {} });
}

function submitAnswer(gameId, questionId, answer) {
  return request(`/api/games/${gameId}/answers`, {
    method: 'POST',
    body: { questionId, answer }
  });
}

function getScore(id) {
  return request(`/api/games/${id}/score`);
}

/* ------------------------------------------------------------------ *
 * Question endpoints (public) – no correct answers exposed
 * ------------------------------------------------------------------ */

function listQuestions(ids) {
  let qs = '';
  if (Array.isArray(ids) && ids.length > 0) {
    qs = `?ids=${ids.join(',')}`;
  }
  return request(`/api/questions${qs}`);
}

/* ------------------------------------------------------------------ *
 * User endpoints
 * ------------------------------------------------------------------ */

function getMe() {
  return request('/api/users/me');
}

/* ------------------------------------------------------------------ *
 * Admin endpoints (require admin role)
 * ------------------------------------------------------------------ */

function listAdminQuestions() {
  return request('/api/admin/questions');
}

function createAdminQuestion(payload) {
  return request('/api/admin/questions', { method: 'POST', body: payload });
}

function deleteAdminQuestion(id) {
  return request(`/api/admin/questions/${id}`, { method: 'DELETE' });
}

/* ------------------------------------------------------------------ *
 * Meta
 * ------------------------------------------------------------------ */

function getHealth() {
  return request('/health');
}

window.SpaceFracApi = {
  TOKEN_KEY,
  getToken,
  setToken,
  hasToken,
  currentClaims,
  isAdmin,
  currentSubject,
  preferredName,
  ApiError,
  createGame,
  getGame,
  pauseGame,
  resumeGame,
  submitAnswer,
  getScore,
  listQuestions,
  getMe,
  listAdminQuestions,
  createAdminQuestion,
  deleteAdminQuestion,
  getHealth
};

/**
 * app.js – application controller.
 *
 * Owns the single-page state machine: introduction -> menu -> play/pause/
 * score/admin views, and wires DOM events to the SpaceFracApi + SpaceFracUi
 * layers. The entire UI runs client-side against the gateway (port 3000).
 */

(function () {
  const Api = window.SpaceFracApi;
  const Ui = window.SpaceFracUi;

  // Current in-memory game context.
  const state = {
    game: null,           // last fetched game (id, state, questions, ...)
    score: 0,
    totalQuestions: 0
  };

  /* ------------------------------------------------------------------ *
   * Navigation
   * ------------------------------------------------------------------ */

  async function showIntroduction() {
    Ui.renderIntroduction();
  }

  async function showMenu() {
    Ui.renderMenu({ isAdmin: Api.isAdmin() });
  }

  async function showHelp() {
    Ui.renderHelp();
  }

  function showPaused() {
    Ui.renderPaused(state.game);
  }

  /* ------------------------------------------------------------------ *
   * Game actions
   * ------------------------------------------------------------------ */

  async function startGame() {
    // Require authentication before creating a game (POST /api/games needs
    // a Bearer token; server returns 401 otherwise).
    if (!Api.hasToken()) {
      Ui.showErrorBanner('Please sign in first to play.');
      openAuthModal();
      return;
    }

    try {
      const game = await Api.createGame();
      state.game = game;
      state.totalQuestions = game.questions.length;
      await loadCurrentQuestion();
    } catch (err) {
      handleError(err);
    }
  }

  async function loadCurrentQuestion() {
    const game = state.game;
    if (!game) return showMenu();

    if (game.state === 'completed') {
      return showEnding();
    }
    if (game.state === 'paused') {
      return showPaused();
    }

    const idx = game.currentQuestionIndex ?? 0;
    const total = game.questions.length;
    const question = game.questions[idx] || null;

    if (!question) {
      return showEnding();
    }

    Ui.renderPlayGame(game, question, {
      question,
      index: idx,
      total
    });

    wirePlayControls(question);
  }

  function wirePlayControls(question) {
    const options = document.querySelectorAll('.option');
    options.forEach((opt) => {
      opt.addEventListener('click', () => {
        options.forEach((o) => o.classList.remove('selected'));
        opt.classList.add('selected');
        const answer = question.options[Number(opt.dataset.optionIndex)];
        document.getElementById('answer-input').value = answer;
        document.getElementById('btn-submit').disabled = false;
      });
    });

    const input = document.getElementById('answer-input');
    if (input) {
      input.addEventListener('input', () => {
        const submitBtn = document.getElementById('btn-submit');
        if (submitBtn) submitBtn.disabled = input.value.trim() === '';
      });
    }

    const submitBtn = document.getElementById('btn-submit');
    if (submitBtn) {
      submitBtn.addEventListener('click', () => submitCurrentAnswer(question));
    }
  }

  async function submitCurrentAnswer(question) {
    const input = document.getElementById('answer-input');
    if (!input) return;
    const answer = input.value.trim();
    if (!answer) return;

    const btn = document.getElementById('btn-submit');
    if (btn) btn.disabled = true;

    try {
      const result = await Api.submitAnswer(state.game.id, question.id, answer);

      // Mark selected option correctness for visual feedback.
      const options = document.querySelectorAll('.option');
      options.forEach((opt) => {
        const text = question.options[Number(opt.dataset.optionIndex)];
        const isChosen = opt.classList.contains('selected');
        if (isChosen) {
          opt.classList.add(result.correct ? 'correct' : 'incorrect');
        }
      });

      Ui.showFeedback(
        result.correct,
        result.correct ? 'Correct!' : 'Not quite — try the next one.',
        result.score
      );

      state.score = result.score;

      if (result.gameState === 'completed') {
        state.game.state = 'completed';
        setTimeout(() => showEnding(), 900);
      } else {
        // Advance to the next question.
        setTimeout(async () => {
          try {
            const refreshed = await Api.getGame(state.game.id);
            state.game = refreshed;
            state.totalQuestions = refreshed.questions.length;
            await loadCurrentQuestion();
          } catch (err) {
            handleError(err);
          }
        }, 1100);
      }
    } catch (err) {
      handleError(err);
      if (btn) btn.disabled = false;
    }
  }

  async function pause() {
    if (!state.game) return;
    try {
      const result = await Api.pauseGame(state.game.id);
      state.game.state = result.state;
      showPaused();
    } catch (err) {
      handleError(err);
    }
  }

  async function resume() {
    if (!state.game) return;
    try {
      const result = await Api.resumeGame(state.game.id);
      state.game.state = result.state;
      await loadCurrentQuestion();
    } catch (err) {
      handleError(err);
    }
  }

  async function showEnding() {
    try {
      let total = state.totalQuestions;
      if (!total && state.game) {
        total = state.game.questions.length;
      }
      Ui.renderEndingFeedback(state.score, total);
    } catch (err) {
      handleError(err);
    }
  }

  async function viewScore() {
    if (!state.game) {
      // No active game: prompt user to play first.
      Ui.renderScoreView(0, 0);
      return;
    }
    try {
      const result = await Api.getScore(state.game.id);
      state.score = result.score;
      Ui.renderScoreView(result.score, state.totalQuestions);
    } catch (err) {
      handleError(err);
    }
  }

  /* ------------------------------------------------------------------ *
   * Admin actions
   * ------------------------------------------------------------------ */

  async function showAdmin() {
    if (!Api.isAdmin()) {
      Ui.showErrorBanner('Administrator access required.');
      return showMenu();
    }
    try {
      const data = await Api.listAdminQuestions();
      Ui.renderAdmin(data.questions || []);
      wireAdminControls();
    } catch (err) {
      handleError(err);
    }
  }

  function wireAdminControls() {
    const form = document.getElementById('admin-create-form');
    if (form) {
      form.addEventListener('submit', async (e) => {
        e.preventDefault();
        const prompt = document.getElementById('admin-prompt').value.trim();
        const options = document.getElementById('admin-options').value
          .split(',').map((s) => s.trim()).filter(Boolean);
        const correctAnswer = document.getElementById('admin-correct').value.trim();

        try {
          await Api.createAdminQuestion({ prompt, options, correctAnswer });
          const fb = document.getElementById('admin-feedback');
          if (fb) {
            fb.textContent = 'Question created.';
            fb.style.color = 'var(--color-success)';
          }
          await showAdmin(); // refresh list
        } catch (err) {
          const fb = document.getElementById('admin-feedback');
          if (fb) {
            fb.textContent = err.message || 'Failed to create question.';
            fb.style.color = 'var(--color-danger)';
          }
        }
      });
    }

    document.querySelectorAll('[data-delete-id]').forEach((btn) => {
      btn.addEventListener('click', async () => {
        const id = btn.dataset.deleteId;
        try {
          await Api.deleteAdminQuestion(id);
          await showAdmin();
        } catch (err) {
          handleError(err);
        }
      });
    });
  }

  /* ------------------------------------------------------------------ *
   * Auth modal
   * ------------------------------------------------------------------ */

  function openAuthModal() {
    document.getElementById('auth-token').value = Api.getToken() || '';
    Ui.openModal('auth-modal');
  }

  function wireAuthModal() {
    document.getElementById('auth-save').addEventListener('click', () => {
      const token = document.getElementById('auth-token').value.trim();
      if (token) {
        Api.setToken(token);
        Ui.closeModal('auth-modal');
        refreshAuth();
        showMenu();
      }
    });
    document.getElementById('auth-cancel').addEventListener('click', () => {
      Ui.closeModal('auth-modal');
    });
    document.getElementById('auth-clear').addEventListener('click', () => {
      Api.setToken(null);
      Ui.closeModal('auth-modal');
      refreshAuth();
      showMenu();
    });
  }

  function refreshAuth() {
    const authed = Api.hasToken();
    const name = Api.preferredName();
    Ui.setSessionStatus(authed, name);
    document.getElementById('btn-auth').textContent = authed ? 'Sign out' : 'Sign in';
  }

  /* ------------------------------------------------------------------ *
   * Global event delegation & boot
   * ------------------------------------------------------------------ */

  function handleError(err) {
    let message = err && err.message ? err.message : 'Something went wrong.';
    if (err && err.status === 401) {
      message = 'Authentication required. Please sign in.';
    } else if (err && err.status === 403) {
      message = 'You are not allowed to do that.';
    } else if (err && err.status === 409) {
      message = message + ' (the game may be paused or already finished).';
    }
    Ui.showErrorBanner(message);
  }

  function wireGlobalEvents() {
    // Delegate clicks on elements carrying data-action.
    document.getElementById('view').addEventListener('click', async (e) => {
      const actionEl = e.target.closest('[data-action]');
      if (!actionEl) return;
      const action = actionEl.dataset.action;
      switch (action) {
        case 'menu': return showMenu();
        case 'play': return startGame();
        case 'score': return viewScore();
        case 'help': return showHelp();
        case 'pause': return pause();
        case 'resume': return resume();
        case 'admin': return showAdmin();
        case 'submit': return; // handled by dedicated listener
        default: break;
      }
    });

    document.getElementById('btn-help').addEventListener('click', () => {
      Ui.openModal('help-modal');
    });
    document.getElementById('help-close').addEventListener('click', () => {
      Ui.closeModal('help-modal');
    });

    document.getElementById('btn-auth').addEventListener('click', () => {
      if (Api.hasToken()) {
        Api.setToken(null);
        refreshAuth();
        showMenu();
      } else {
        openAuthModal();
      }
    });

    wireAuthModal();
  }

  async function boot() {
    refreshAuth();
    wireGlobalEvents();
    // Start at the introduction.
    await showIntroduction();
  }

  document.addEventListener('DOMContentLoaded', boot);
})();

