/**
 * Unit tests for the admin-service question validation and serialization.
 *
 * The admin routes module requires `@spacefractions/shared/*` (auth, errors,
 * db, metrics) and the question-service search helper (`@elastic/elasticsearch`).
 * All of these are lazy at require time (no DB/ES connection is established
 * merely by importing), so the pure helpers `validateQuestionPayload` and
 * `toAdminQuestion` can be exercised without live infrastructure.
 */
const { test } = require('node:test');
const assert = require('node:assert/strict');

const { BadRequestError } = require('@spacefractions/shared/errors');
const { formatFraction } = require('@spacefractions/shared/fraction');
const { validateQuestionPayload, toAdminQuestion } = require('../src/routes');

/**
 * A minimal valid payload and the expected normalized correctAnswer.
 */
const VALID = {
  prompt: '  What is 1/2 of 1/2?  ',
  options: ['1/2', '1/4', '3/4', '1'],
  correctAnswer: '1/4'
};

test('validateQuestionPayload normalizes a valid payload', () => {
  const result = validateQuestionPayload(VALID);
  assert.equal(result.prompt, 'What is 1/2 of 1/2?');
  assert.deepEqual(result.options, ['1/2', '1/4', '3/4', '1']);
  assert.equal(result.correctAnswer, '1/4');
});

test('validateQuestionPayload normalizes equivalent correctAnswer to canonical form', () => {
  // "2/4" is listed as "1/4"? No — use an equivalent: list "2/8" is not present.
  // Instead, list "1/2" and supply correctAnswer "2/4" (equal rational).
  const result = validateQuestionPayload({
    prompt: 'p',
    options: ['1/2', '1/3'],
    correctAnswer: '2/4'
  });
  assert.equal(result.correctAnswer, formatFraction('2/4')); // "1/2"
});

test('validateQuestionPayload rejects a null body', () => {
  assert.throws(() => validateQuestionPayload(null), BadRequestError);
  assert.throws(() => validateQuestionPayload('string'), BadRequestError);
});

test('validateQuestionPayload rejects a missing or empty prompt', () => {
  assert.throws(
    () => validateQuestionPayload({ options: ['1/2', '1/4'], correctAnswer: '1/4' }),
    (err) => err instanceof BadRequestError && /prompt/.test(err.message)
  );
  assert.throws(
    () => validateQuestionPayload({ prompt: '   ', options: ['1/2', '1/4'], correctAnswer: '1/4' }),
    (err) => err instanceof BadRequestError && /prompt/.test(err.message)
  );
});

test('validateQuestionPayload rejects a non-string prompt', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 42, options: ['1/2', '1/4'], correctAnswer: '1/4' }),
    BadRequestError
  );
});

test('validateQuestionPayload rejects options that are not an array', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: '1/2', correctAnswer: '1/2' }),
    BadRequestError
  );
});

test('validateQuestionPayload rejects too few options', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2'], correctAnswer: '1/2' }),
    (err) => err instanceof BadRequestError && /between 2 and 10/.test(err.message)
  );
});

test('validateQuestionPayload rejects too many options', () => {
  const options = Array.from({ length: 11 }, (_, i) => `1/${i + 1}`);
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options, correctAnswer: options[0] }),
    (err) => err instanceof BadRequestError && /between 2 and 10/.test(err.message)
  );
});

test('validateQuestionPayload rejects blank or non-string options', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', ''], correctAnswer: '1/2' }),
    BadRequestError
  );
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', 5], correctAnswer: '1/2' }),
    BadRequestError
  );
});

test('validateQuestionPayload rejects duplicate options', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', '1/2'], correctAnswer: '1/2' }),
    (err) => err instanceof BadRequestError && /duplicate/i.test(err.message)
  );
});

test('validateQuestionPayload rejects a malformed correctAnswer', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', '1/4'], correctAnswer: 'abc' }),
    (err) => err instanceof BadRequestError && /well-formed fraction/.test(err.message)
  );
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', '1/4'], correctAnswer: '1/0' }),
    (err) => err instanceof BadRequestError && /well-formed fraction/.test(err.message)
  );
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', '1/4'], correctAnswer: '' }),
    BadRequestError
  );
});

test('validateQuestionPayload rejects correctAnswer not present among options', () => {
  assert.throws(
    () => validateQuestionPayload({ prompt: 'p', options: ['1/2', '1/4'], correctAnswer: '3/4' }),
    (err) => err instanceof BadRequestError && /one of the provided options/.test(err.message)
  );
});

test('validateQuestionPayload accepts an equivalent correctAnswer listed as an option', () => {
  // "2/4" equals "1/2" which IS listed, so this should validate.
  const result = validateQuestionPayload({
    prompt: 'p',
    options: ['3/4', '1/2'],
    correctAnswer: '2/4'
  });
  assert.equal(result.correctAnswer, '1/2');
});

test('toAdminQuestion maps a DB row to an admin response shape', () => {
  const row = {
    id: 5,
    prompt: 'What is 1/4 + 1/4?',
    options: ['1/4', '1/2', '3/4', '1'],
    correct_answer: '1/2',
    created_by: 9,
    created_at: new Date('2024-01-01T00:00:00Z'),
    updated_at: new Date('2024-01-02T00:00:00Z')
  };
  const result = toAdminQuestion(row);
  assert.deepEqual(result, {
    id: 5,
    prompt: 'What is 1/4 + 1/4?',
    options: ['1/4', '1/2', '3/4', '1'],
    correctAnswer: '1/2',
    createdBy: 9,
    createdAt: row.created_at,
    updatedAt: row.updated_at
  });
});

/**
 * Canonical OIDC subject -> internal `users.id` resolution.
 *
 * The `users` table owns the mapping from the OIDC `sub` claim (a stable,
 * provider-issued string, e.g. a Keycloak UUID) to a numeric internal id used
 * as the foreign key for game ownership (`games.user_id`) and question
 * authorship (`questions.created_by`).
 *
 * Every service that needs an internal numeric user id MUST resolve it through
 * this function (rather than relying on the raw `sub`), so that game-service,
 * user-service and admin-service all agree on the same identity mapping.
 *
 * The resolution is an idempotent upsert on the unique `sub` column: if a row
 * already exists it is loaded (and its username/email refreshed), otherwise a
 * new row is created. Concurrent callers are safe thanks to `ON CONFLICT`.
 */

const { query, queryOne } = require('./db');
const { BadRequestError } = require('./errors');

/**
 * Resolve and return the numeric internal `users.id` for an authenticated
 * caller's OIDC claims, creating the row on first sight (idempotent).
 *
 * @param {object} claims - decoded (and already verified) OIDC token payload.
 * @returns {Promise<number>} the numeric `users.id`.
 * @throws {BadRequestError} when the claims lack a `sub`.
 */
async function resolveInternalUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }

  const username =
    claims.preferred_username ||
    claims.email ||
    claims.name ||
    `user-${String(sub).slice(0, 8)}`;
  const email = claims.email || null;

  const existing = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  if (existing) {
    // Keep the human-readable fields fresh (best effort).
    await query(
      `UPDATE users SET username = $2, email = COALESCE($3, email) WHERE id = $1`,
      [existing.id, username, email]
    );
    return existing.id;
  }

  const result = await query(
    `INSERT INTO users (sub, username, email)
     VALUES ($1, $2, $3)
     ON CONFLICT (sub) DO UPDATE SET
       username = EXCLUDED.username,
       email = COALESCE(EXCLUDED.email, users.email)
     RETURNING id`,
    [sub, username, email]
  );

  return result.rows[0].id;
}

module.exports = { resolveInternalUserId };

/**
 * Admin Service – HTTP Routes
 *
 * Authenticated administrator-only question CRUD. Mounted under
 * /api/admin by the gateway (and directly on this service).
 *
 *   POST   /api/admin/questions            – create question (201)
 *   GET    /api/admin/questions            – list questions (includes correct_answer)
 *   GET    /api/admin/questions/:id        – single question (includes correct_answer)
 *   PUT    /api/admin/questions/:id        – update question
 *   DELETE /api/admin/questions/:id        – delete question (204)
 *
 * Authorization: every route requires a valid Bearer OIDC access token AND
 * the `admin` realm role. Unauthenticated requests yield 401; authenticated
 * non-admin requests yield 403 (per the acceptance contract).
 *
 * Server-side validation:
 *   - prompt must be a non-empty string
 *   - options must be an array of 2..10 non-empty strings
 *   - correctAnswer must be a well-formed exact rational ("a/b" or integer)
 *   - correctAnswer must be one of options (the correct answer is always a
 *     listed option, matching the multiple-choice model)
 */

const { Router } = require('express');
const { requireAuth, requireAdmin } = require('@spacefractions/shared/auth');
const {
  BadRequestError,
  NotFoundError,
  ConflictError,
} = require('@spacefractions/shared/errors');
const { query, queryOne } = require('@spacefractions/shared/db');
const { isValidFraction, fractionsEqual, formatFraction } = require('@spacefractions/shared/fraction');
const { questionsCreated } = require('@spacefractions/shared/metrics');
const { indexQuestion, deleteQuestion: deleteQuestionDoc } = require('../../question-service/src/search');

const { resolveInternalUserId } = require('@spacefractions/shared/identity');

const router = Router();

const LIMIT_MAX = 500;
const OPTIONS_MIN = 2;
const OPTIONS_MAX = 10;

/**
 * Normalize and validate a question payload ({ prompt, options, correctAnswer }).
 * Returns the normalized { prompt, options, correctAnswer } on success.
 * Throws BadRequestError for malformed input.
 */
function validateQuestionPayload(body) {
  if (typeof body !== 'object' || body === null) {
    throw new BadRequestError('Request body must be a JSON object');
  }

  const { prompt, options, correctAnswer } = body;

  // prompt: non-empty string with a length cap
  if (typeof prompt !== 'string' || prompt.trim() === '') {
    throw new BadRequestError('prompt must be a non-empty string');
  }
  if (prompt.length > 2000) {
    throw new BadRequestError('prompt exceeds maximum length of 2000 characters');
  }

  // options: array of 2..10 non-empty strings, no duplicates (after trim)
  if (!Array.isArray(options)) {
    throw new BadRequestError('options must be an array of strings');
  }
  if (options.length < OPTIONS_MIN || options.length > OPTIONS_MAX) {
    throw new BadRequestError(
      `options must contain between ${OPTIONS_MIN} and ${OPTIONS_MAX} strings`
    );
  }
  const seen = new Set();
  for (const opt of options) {
    if (typeof opt !== 'string' || opt.trim() === '') {
      throw new BadRequestError('each option must be a non-empty string');
    }
    if (opt.length > 200) {
      throw new BadRequestError('an option exceeds maximum length of 200 characters');
    }
    if (seen.has(opt.trim())) {
      throw new BadRequestError('options must not contain duplicates');
    }
    seen.add(opt.trim());
  }

  // correctAnswer: well-formed exact fraction AND one of the options
  if (typeof correctAnswer !== 'string' || correctAnswer.trim() === '') {
    throw new BadRequestError('correctAnswer must be a non-empty string');
  }
  if (!isValidFraction(correctAnswer)) {
    throw new BadRequestError(
      'correctAnswer must be a well-formed fraction ("a/b", denominator != 0)'
    );
  }
  // The correct answer must appear among the options (compare as exact
  // rationals so "1/2" and "2/4" are considered the same answer).
  const normalizedCorrect = formatFraction(correctAnswer);
  const optionMatches = options.some((opt) => fractionsEqual(opt, correctAnswer));
  if (!optionMatches) {
    throw new BadRequestError('correctAnswer must be one of the provided options');
  }

  return {
    prompt: prompt.trim(),
    options,
    correctAnswer: normalizedCorrect,
  };
}

/**
 * Serialize a question row for admin responses (includes correct_answer).
 */
function toAdminQuestion(row) {
  return {
    id: row.id,
    prompt: row.prompt,
    options: row.options,
    correctAnswer: row.correct_answer,
    createdBy: row.created_by,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

/**
 * Resolve the internal user id for the authenticated caller (from OIDC `sub`).
 * Used to stamp `created_by` on new questions and to authorize ownership.
 */
async function resolveCallerUserId(claims) {
  const sub = claims && claims.sub;
  if (!sub) {
    throw new BadRequestError('Token missing subject (sub) claim');
  }
  const row = await queryOne('SELECT id FROM users WHERE sub = $1', [sub]);
  return row ? row.id : null;
}

// Apply auth middlewares to all admin routes. Order matters: requireAuth
// populates req.user, then requireAdmin enforces the realm role.
router.use(requireAuth, requireAdmin);

/**
 * GET /api/admin/questions
 * List all questions (with correct_answer), newest first. Optional ?limit.
 */
router.get('/questions', async (req, res, next) => {
  try {
    const limit = req.query.limit ? parseInt(req.query.limit, 10) : LIMIT_MAX;
    if (Number.isNaN(limit) || limit < 1 || limit > LIMIT_MAX) {
      throw new BadRequestError(`limit must be between 1 and ${LIMIT_MAX}`);
    }

    const result = await query(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions
       ORDER BY created_at DESC
       LIMIT $1`,
      [limit]
    );

    res.json({
      questions: result.rows.map(toAdminQuestion),
      count: result.rows.length,
    });
  } catch (err) {
    next(err);
  }
});

/**
 * GET /api/admin/questions/:id
 * Single question (with correct_answer).
 */
router.get('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const row = await queryOne(
      `SELECT id, prompt, options, correct_answer, created_by, created_at, updated_at
       FROM questions WHERE id = $1`,
      [id]
    );

    if (!row) {
      throw new NotFoundError('Question not found');
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * POST /api/admin/questions
 * Create a question. Body: { prompt, options: [string], correctAnswer }.
 * Returns 201 with the created question.
 */
router.post('/questions', async (req, res, next) => {
  try {
    const normalized = validateQuestionPayload(req.body);
    const createdBy = await resolveCallerUserId(req.user);

    const result = await query(
      `INSERT INTO questions (prompt, options, correct_answer, created_by)
       VALUES ($1, $2, $3, $4)
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
        createdBy,
      ]
    );

    const row = result.rows[0];

    // Best-effort Elasticsearch indexing (non-fatal).
    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    questionsCreated.inc();

    res.status(201).json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * PUT /api/admin/questions/:id
 * Update (replace) a question. Same validation as create.
 */
router.put('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const existing = await queryOne('SELECT id FROM questions WHERE id = $1', [id]);
    if (!existing) {
      throw new NotFoundError('Question not found');
    }

    const normalized = validateQuestionPayload(req.body);

    const result = await query(
      `UPDATE questions
       SET prompt = $2, options = $3, correct_answer = $4, updated_at = NOW()
       WHERE id = $1
       RETURNING id, prompt, options, correct_answer, created_by, created_at, updated_at`,
      [
        id,
        normalized.prompt,
        JSON.stringify(normalized.options),
        normalized.correctAnswer,
      ]
    );

    const row = result.rows[0];

    try {
      await indexQuestion({ id: row.id, prompt: row.prompt, options: row.options });
    } catch (err) {
      console.warn('Admin service: index question failed:', err.message);
    }

    res.json(toAdminQuestion(row));
  } catch (err) {
    next(err);
  }
});

/**
 * DELETE /api/admin/questions/:id
 * Delete a question. Returns 204 No Content on success.
 */
router.delete('/questions/:id', async (req, res, next) => {
  try {
    const id = parseInt(req.params.id, 10);
    if (!Number.isInteger(id) || id <= 0) {
      throw new BadRequestError('Invalid question id');
    }

    const result = await query('DELETE FROM questions WHERE id = $1 RETURNING id', [id]);

    if (result.rows.length === 0) {
      throw new NotFoundError('Question not found');
    }

    try {
      await deleteQuestionDoc(id);
    } catch (err) {
      console.warn('Admin service: delete question doc failed:', err.message);
    }

    res.status(204).end();
  } catch (err) {
    next(err);
  }
});

module.exports = router;
module.exports.validateQuestionPayload = validateQuestionPayload;
module.exports.toAdminQuestion = toAdminQuestion;

/**
 * Game Engine – core game logic for Space Fractions.
 *
 * States: 'playing', 'paused', 'completed'
 * Transitions:
 *   playing  -> paused   (pause)
 *   paused   -> playing  (resume)
 *   playing  -> completed (all questions answered)
 *
 * Scoring:
 *   - Each correct answer to a not-yet-correctly-answered question: +1
 *   - Re-answering correctly: idempotent (no score change)
 *   - Score never decreases
 */

const { query, queryOne, withTransaction } = require('@spacefractions/shared/db');
const { fractionsEqual, isValidFraction } = require('@spacefractions/shared/fraction');
const { BadRequestError, ConflictError, NotFoundError } = require('@spacefractions/shared/errors');

/**
 * Create a new game for the given user with the specified questions.
 */
async function createGame(userId, questionIds) {
  // If no question IDs provided, fetch all available questions
  if (!questionIds || questionIds.length === 0) {
    const result = await query('SELECT id FROM questions ORDER BY created_at');
    questionIds = result.rows.map(r => r.id);
  }

  if (questionIds.length === 0) {
    throw new BadRequestError('No questions available to create a game');
  }

  const result = await query(
    `INSERT INTO games (user_id, state, score, question_ids, current_question_index)
     VALUES ($1, 'playing', 0, $2, 0)
     RETURNING *`,
    [userId, questionIds]
  );

  return result.rows[0];
}

/**
 * Get a game by ID. Validates ownership (unless isAdmin).
 */
async function getGame(gameId, userId, isAdmin) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) {
    throw new NotFoundError('Game not found');
  }

  // Authorization: only owner or admin can access
  if (!isAdmin && game.user_id !== userId) {
    throw new NotFoundError('Game not found');
  }

  return game;
}

/**
 * Get the current question for a game.
 */
async function getCurrentQuestion(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'completed') {
    return null;
  }

  const idx = game.current_question_index;
  if (idx >= game.question_ids.length) {
    return null;
  }

  const qId = game.question_ids[idx];
  const question = await queryOne(
    'SELECT id, prompt, options FROM questions WHERE id = $1',
    [qId]
  );

  return question;
}

/**
 * Pause a game. Only valid from 'playing' state.
 */
async function pauseGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'paused') {
    // Already paused – idempotent
    return game;
  }

  if (game.state !== 'playing') {
    throw new ConflictError(`Cannot pause game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'paused', updated_at = NOW()
     WHERE id = $1 AND state = 'playing'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Resume a game. Only valid from 'paused' state.
 */
async function resumeGame(gameId) {
  const game = await queryOne('SELECT * FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');

  if (game.state === 'playing') {
    // Already playing – idempotent
    return game;
  }

  if (game.state !== 'paused') {
    throw new ConflictError(`Cannot resume game in state: ${game.state}`);
  }

  const result = await query(
    `UPDATE games SET state = 'playing', updated_at = NOW()
     WHERE id = $1 AND state = 'paused'
     RETURNING *`,
    [gameId]
  );

  if (!result.rows[0]) {
    throw new ConflictError('Game state changed concurrently');
  }

  return result.rows[0];
}

/**
 * Submit an answer for a question in a game.
 * Returns { correct, score, gameState }.
 *
 * Idempotent: re-answering the same question never increases score a second
 * time, because the score increment is gated on the atomic `scored`
 * FALSE -> TRUE transition of the single answer row (guarded by the
 * UNIQUE (game_id, question_id) constraint).
 *
 * Concurrency: the whole mutation runs in one transaction holding a
 * `SELECT ... FOR UPDATE` lock on the game row AND the answer
 * deduplication, score increment, progress advance and state transition are
 * performed in a SINGLE data-modifying CTE statement. This means the
 * FALSE -> TRUE detection and the `score = score + 1` happen in one atomic
 * unit: a concurrent duplicate submission cannot both observe a
 * FALSE -> TRUE transition and double-increment the score, even in the
 * absence of the row lock.
 */
async function submitAnswer(gameId, questionId, answer, userId, isAdmin, publishScoreEvent) {
  // Basic validation outside the transaction: a malformed fraction or an
  // out-of-game question cannot possibly score.
  if (!isValidFraction(answer)) {
    throw new BadRequestError('Malformed fraction answer');
  }

  return withTransaction(async (tx) => {
    // Lock the game row for the duration of the transaction. This serializes
    // concurrent submissions against the same game and (re)checks ownership,
    // pause and completion state atomically with the score mutation.
    const game = await tx.queryOne(
      'SELECT * FROM games WHERE id = $1 FOR UPDATE',
      [gameId]
    );
    if (!game) {
      throw new NotFoundError('Game not found');
    }
    if (!isAdmin && game.user_id !== userId) {
      throw new NotFoundError('Game not found');
    }

    if (game.state === 'paused') {
      throw new ConflictError('Cannot answer while game is paused');
    }

    // The question must actually belong to this game.
    if (!game.question_ids.includes(questionId)) {
      throw new BadRequestError('Question is not part of this game');
    }

    // Resolve the correct answer.
    const question = await tx.queryOne(
      'SELECT id, correct_answer FROM questions WHERE id = $1',
      [questionId]
    );
    if (!question) {
      throw new NotFoundError('Question not found');
    }

    const correct = fractionsEqual(answer, question.correct_answer);

    const completed = game.current_question_index >= game.question_ids.length;

    // Completed games: only an idempotent replay of an already-scored
    // question is permitted (returns current score without error).
    if (game.state === 'completed' || completed) {
      const replayed = await tx.queryOne(
        'SELECT scored FROM game_answers WHERE game_id = $1 AND question_id = $2',
        [gameId, questionId]
      );
      if (replayed && replayed.scored) {
        return { correct: true, score: game.score, gameState: 'completed' };
      }
      throw new ConflictError('Game is already completed');
    }

    // Atomic answer upsert + score increment + progress/state mutation, all in
    // ONE data-modifying CTE statement.
    //
    //  - answer_upsert: flips the single answer row's `scored` from FALSE to
    //    TRUE only on the FIRST correct answer (guarded by the UNIQUE
    //    (game_id, question_id) constraint), and returns `newly_scored`
    //    exactly once for that transition.
    //  - game_update: reads the CURRENT game score from the row and increments
    //    it only by `newly_scored`. Because this happens in the same statement
    //    as the dedup decision, two concurrent submissions of the same
    //    question cannot both observe a FALSE -> TRUE transition: the second
    //    one sees `scored = TRUE` already and its increment is 0.
    //  - Progress advances only when the answered question is the one at the
    //    current index (computed from the row's question_ids array, so it is
    //    not derived from a stale pre-lock JS read) and the game row flips to
    //    'completed' only when that advance exhausts the question list.
    const row = await tx.queryOne(
      `WITH answer_upsert AS (
         INSERT INTO game_answers (game_id, question_id, answer, correct, scored)
         VALUES ($1, $2, $3, $4, $4)
         ON CONFLICT (game_id, question_id) DO UPDATE SET
           answer = EXCLUDED.answer,
           correct = EXCLUDED.correct,
           scored = CASE
             WHEN game_answers.scored = FALSE AND EXCLUDED.scored = TRUE THEN TRUE
             ELSE game_answers.scored
           END
         RETURNING
           (CASE WHEN game_answers.scored = FALSE AND EXCLUDED.scored = TRUE THEN TRUE ELSE FALSE END) AS newly_scored,
           correct AS is_correct
       ),
       game_update AS (
         UPDATE games g
         SET score = g.score + (SELECT newly_scored::int FROM answer_upsert),
             current_question_index = CASE
               WHEN g.question_ids[g.current_question_index + 1] = $2 THEN g.current_question_index + 1
               ELSE g.current_question_index
             END,
             state = CASE
               WHEN g.question_ids[g.current_question_index + 1] = $2
                    AND (g.current_question_index + 1) >= array_length(g.question_ids, 1)
               THEN 'completed'
               ELSE g.state
             END,
             updated_at = NOW()
         WHERE g.id = $1
         RETURNING g.score, g.current_question_index, g.state
       )
       SELECT
         (SELECT newly_scored FROM answer_upsert) AS newly_scored,
         (SELECT is_correct FROM answer_upsert) AS correct,
         (SELECT score FROM game_update) AS score,
         (SELECT state FROM game_update) AS state`,
      [gameId, questionId, answer, correct]
    );

    const newlyScored = row && row.newly_scored === true;
    const finalScore = numberScore(row.score);
    const finalState = row.state;

    if (newlyScored && publishScoreEvent) {
      try {
        publishScoreEvent(gameId, userId, finalScore, questionId);
      } catch {
        // Non-critical; do not fail the transaction over telemetry.
      }
    }

    return {
      correct,
      score: finalScore,
      gameState: finalState
    };
  });
}

function numberScore(v) {
  return typeof v === 'number' ? v : parseInt(v, 10);
}

/**
 * Get the score for a game.
 */
async function getScore(gameId) {
  const game = await queryOne('SELECT id, score, state FROM games WHERE id = $1', [gameId]);
  if (!game) throw new NotFoundError('Game not found');
  return { score: game.score, state: game.state };
}

